            best_str = (
                f" | Best Strategy: {self._state.best_strategy}"
                if self._state.best_strategy
                else ""
            )
            indicator.update(f"Last refresh: {self._state.last_refresh}{best_str}")
        except Exception:
            pass

    def action_refresh(self) -> None:
        self._refresh_state()

